129			var matches int
130			for pattern := range cfg.Models {
131				matched, err := filepath.Match(pattern, entry)
132				if err == nil && matched {
133					matches++
134				}
135			}
136			if matches == 0 {
137				return fmt.Errorf("warmup entry %q does not match any model pattern", entry)
138			}
139			if matches > 1 {
140				return fmt.Errorf("warmup entry %q matches %d model patterns (expected 1)", entry, matches)
141			}
142		}
143		if len(cfg.Warmup) > cfg.MaxModels {
144			return fmt.Errorf("warmup list length %d exceeds max_models %d", len(cfg.Warmup), cfg.MaxModels)
145		}
146		validSpecTypes := map[string]bool{
147			"ngram-simple":  true,
