1	package gateway
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"log/slog"
11		"net/http"
12		"net/http/httputil"
13		"net/url"
14		"sync/atomic"
15		"time"
16	
17		"github.com/nogo/wire/internal/config"
18		"github.com/nogo/wire/internal/monitor"
19		"github.com/nogo/wire/internal/process"
20	)
21	
22	// nctxProvider wraps the NCtx lookup; *monitor.Hub satisfies this interface.
23	type nctxProvider interface {
24		NCtx(model string) int
25	}
26	
27	// backendManager is the subset of process.Manager the Gateway depends on.
28	type backendManager interface {
29		Loaded(name string) bool
30		// LoadOrGet returns the backend address for the named model, loading it on
31		// demand if not already running. The caller must call release() when the
32		// proxied request completes to decrement the in-flight counter.
33		LoadOrGet(ctx context.Context, modelName string, params config.ModelParams) (addr string, release func(), err error)
34		// ListModels returns all known models in non-idle states.
35		ListModels() []monitor.ModelInfo
36	}
37	
38	// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
39	type Gateway struct {
40		cfg      atomic.Pointer[config.Config]
41		mgr      backendManager
42		log      *slog.Logger
43		affinity *affinityTable
44		hub      nctxProvider
45		server   *http.Server
46	}
47	
48	// New creates a Gateway backed by the given process manager.
49	// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
50	func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, log *slog.Logger) *Gateway {
51		return newGateway(cfg, mgr, hub, log)
52	}
53	
54	func newGateway(cfg *config.Config, mgr backendManager, hub *monitor.Hub, log *slog.Logger) *Gateway {
55		// Build affinity table from warmup models.
56		modelSlots := make(map[string]int, len(cfg.Warmup))
57		for _, name := range cfg.Warmup {
58			if params, ok := cfg.MatchModel(name); ok {
59				modelSlots[name] = params.Slots
60			}
61		}
62	
63		g := &Gateway{mgr: mgr, log: log, affinity: newAffinityTable(modelSlots)}
64		g.cfg.Store(cfg)
65		// Store hub as nctxProvider nil-safely: a nil *monitor.Hub must not become
66		// a non-nil interface value, which would cause g.hub == nil checks to fail.
67		if hub != nil {
68			g.hub = hub
69		}
70	
71		mux := http.NewServeMux()
72		mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
73		mux.HandleFunc("POST /v1/completions", g.handleRoute)
74		mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
75		mux.HandleFunc("POST /v1/rerank", g.handleRoute)
76		mux.HandleFunc("GET /v1/models", g.handleModels)
77		mux.HandleFunc("GET /health", g.handleHealth)
78	
79		if hub != nil {
80			mux.HandleFunc("GET /monitor", monitor.HandlePage)
81			mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
82		}
83	
84		g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
85		return g
86	}
87	
88	// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
89	func (g *Gateway) ListenAndServe(ctx context.Context) error {
90		errCh := make(chan error, 1)
91		go func() {
92			if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
93				errCh <- err
94			}
95		}()
96		select {
97		case err := <-errCh:
98			return err
99		case <-ctx.Done():
100			shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
101			defer cancel()
102			return g.server.Shutdown(shutCtx)
103		}
104	}
105	
106	// UpdateConfig atomically replaces the gateway's config. New requests will use
107	// the updated model patterns and params immediately.
108	func (g *Gateway) UpdateConfig(cfg *config.Config) {
109		g.cfg.Store(cfg)
110	}
111	
112	// handleRoute extracts the model field from the JSON body and proxies to the matching process.
113	// If the model is known but not loaded, it is started on demand; the HTTP connection
114	// is held open until the model becomes healthy.
115	func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
116		// Tee the body so the decoder and the upstream both see it.
117		var captured bytes.Buffer
118		tee := io.TeeReader(r.Body, &captured)
119		dec := json.NewDecoder(tee)
120	
121		var payload struct {
122			Model string `json:"model"`
123		}
124		if err := dec.Decode(&payload); err != nil {
125			writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
126			return
127		}
128		if payload.Model == "" {
129			writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
130			return
131		}
132	
133		// Reconstruct full body: captured bytes (read by decoder) + rest not yet read.
134		r.Body = io.NopCloser(io.MultiReader(&captured, r.Body))
135	
136		params, ok := g.cfg.Load().MatchModel(payload.Model)
137		if !ok {
138			writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
139			return
140		}
141	
142		// LoadOrGet blocks until the model is healthy (or fails). The load context is
143		// detached from the caller's request context inside the manager, so a client
144		// disconnect does not abort an in-progress load that other requests may share.
145		addr, release, err := g.mgr.LoadOrGet(r.Context(), payload.Model, params)
146		if err != nil {
147			if errors.Is(err, context.DeadlineExceeded) {
148				writeError(w, http.StatusGatewayTimeout, "server_error", "model load timed out: "+err.Error(), "load_timeout")
149				return
150			}
151			writeError(w, http.StatusServiceUnavailable, "server_error", err.Error(), "model_not_loaded")
152			return
153		}
154		defer release()
155	
156		// Context window guard: reject requests that would exceed 90% of n_ctx.
157		// Best-effort: skipped when hub is nil, n_ctx is unknown, or estimation fails.
158		if g.hub != nil {
159			if nCtx := g.hub.NCtx(payload.Model); nCtx > 0 {
160				if est := estimateTokens(captured.Bytes()); est > 0 {
161					if est > nCtx*9/10 {
162						writeError(w, http.StatusBadRequest, "invalid_request_error",
163							fmt.Sprintf("estimated %d tokens exceeds context window of %d (n_ctx)", est, nCtx),
164							"context_length_exceeded")
165						return
166					}
167				}
168			}
169		}
170	
171		// Register affinity entry for the newly loaded model (idempotent for warmup models).
172		g.affinity.Register(payload.Model, params.Slots)
173	
174		// Slot affinity: read full body, compute prefix hash, inject id_slot if assigned.
175		// On any error, fall through with the original body unchanged.
176		if allBody, readErr := io.ReadAll(r.Body); readErr == nil {
177			hash := prefixHash(allBody)
178			if slotID, assigned := g.affinity.Assign(payload.Model, hash); assigned {
179				allBody = injectSlot(allBody, slotID)
180			}
181			r.Body = io.NopCloser(bytes.NewReader(allBody))
182			r.ContentLength = int64(len(allBody))
183		}
184	
185		target, parseErr := url.Parse(addr)
186		if parseErr != nil {
187			writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
188			return
189		}
190	
191		proxy := &httputil.ReverseProxy{
192			Rewrite: func(pr *httputil.ProxyRequest) {
193				pr.SetURL(target)
194				pr.Out.Host = target.Host
195			},
196			FlushInterval:  -1,
197			ModifyResponse: rewriteContextLengthError,
198			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
199				g.log.Error("proxy error", "model", payload.Model, "error", err)
200				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
201			},
202		}
203	
204		proxy.ServeHTTP(w, r)
205	}
206	
207	// handleModels returns all known models with their current status.
208	func (g *Gateway) handleModels(w http.ResponseWriter, _ *http.Request) {
209		type modelObj struct {
210			ID      string `json:"id"`
211			Object  string `json:"object"`
212			OwnedBy string `json:"owned_by"`
213			Status  string `json:"status,omitempty"`
214		}
215		type modelsResp struct {
216			Object string     `json:"object"`
217			Data   []modelObj `json:"data"`
218		}
219	
220		models := g.mgr.ListModels()
221		data := make([]modelObj, len(models))
222		for i, mi := range models {
223			data[i] = modelObj{
224				ID:      mi.ID,
225				Object:  "model",
226				OwnedBy: "wire",
227				Status:  mi.Status,
228			}
229		}
230	
231		w.Header().Set("Content-Type", "application/json")
232		json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
233	}
234	
235	// handleHealth returns 200 if at least one warmup model is healthy, 503 otherwise.
236	func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
237		w.Header().Set("Content-Type", "application/json")
238		for _, name := range g.cfg.Load().Warmup {
239			if g.mgr.Loaded(name) {
240				w.WriteHeader(http.StatusOK)
241				json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
242				return
243			}
244		}
245		w.WriteHeader(http.StatusServiceUnavailable)
246		json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
247	}
248	
249	// estimateTokens approximates the token count of a request body using a
250	// chars/4 heuristic. It extracts text from messages[].content (chat) and the
251	// input field (embeddings). Returns 0 on parse failure or empty content.
252	func estimateTokens(body []byte) int {
253		var req struct {
254			Messages []struct {
255				Content json.RawMessage `json:"content"`
256			} `json:"messages"`
257			Input json.RawMessage `json:"input"`
258		}
259		if err := json.Unmarshal(body, &req); err != nil {
260			return 0
261		}
262	
263		total := 0
264		for _, msg := range req.Messages {
265			if len(msg.Content) == 0 {
266				continue
267			}
268			var s string
269			if err := json.Unmarshal(msg.Content, &s); err == nil {
270				total += len(s)
271				continue
272			}
273			var parts []struct {
274				Text string `json:"text"`
275			}
276			if err := json.Unmarshal(msg.Content, &parts); err == nil {
277				for _, p := range parts {
278					total += len(p.Text)
279				}
280			}
281		}
282	
283		if len(req.Input) > 0 {
284			var s string
285			if err := json.Unmarshal(req.Input, &s); err == nil {
286				total += len(s)
287			} else {
288				var arr []string
289				if err := json.Unmarshal(req.Input, &arr); err == nil {
290					for _, s := range arr {
291						total += len(s)
292					}
293				}
294			}
295		}
296	
297		return total / 4
298	}
299	
300	// rewriteContextLengthError inspects non-2xx upstream responses for a
301	// context_length_exceeded error code and rewrites the status to 400 to match
302	// the OpenAI API standard. llama-server returns these as 500.
303	func rewriteContextLengthError(resp *http.Response) error {
