332	// TestLoadOrGet_Coalescing verifies that 10 concurrent requests for the same
333	// unloaded model coalesce to a single process start.
334	func TestLoadOrGet_Coalescing(t *testing.T) {
335		cfg := &config.Config{
336			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
337			MaxModels: 1,
338		}
339		m := New(cfg, slog.Default())
340		// 200 ms startup delay to ensure all goroutines arrive before healthy.
341		m.cmdBuilder = testCmdBuilderWithDelay(200)
342	
343		ctx, cancel := context.WithCancel(context.Background())
344		defer cancel()
345		if err := m.Start(ctx); err != nil {
346			t.Fatalf("Start: %v", err)
347		}
348	
349		params := config.ModelParams{Slots: 1}
350		const n = 10
351		addrs := make([]string, n)
352		var wg sync.WaitGroup
353		wg.Add(n)
354		for i := range n {
355			go func(i int) {
356				defer wg.Done()
357				addr, release, err := m.LoadOrGet(ctx, "org/model-a", params)
358				if err != nil {
359					t.Errorf("goroutine %d: LoadOrGet error: %v", i, err)
360					return
361				}
362				defer release()
363				addrs[i] = addr
364			}(i)
365		}
366		wg.Wait()
367	
368		// All goroutines must have gotten a non-empty addr.
369		first := addrs[0]
370		if first == "" {
371			t.Fatal("got empty addr")
372		}
373		for i, a := range addrs {
374			if a != first {
375				t.Errorf("goroutine %d: got addr %q, want %q (coalescing failed)", i, a, first)
376			}
377		}
378	
379		// Only one process should have been started.
380		if len(m.RunningModels()) != 1 {
381			t.Errorf("RunningModels: expected 1, got %d", len(m.RunningModels()))
382		}
383	}
