770	// waitLoadedModel polls until the named model is healthy or the deadline passes.
771	func waitLoadedModel(t *testing.T, m *Manager, name string, timeout time.Duration) {
772		t.Helper()
773		deadline := time.Now().Add(timeout)
774		for time.Now().Before(deadline) {
