package config

import (
	"context"
	"log/slog"
	"os"
	"path/filepath"
	"testing"
	"time"
)

const (
	validWatchYAML = `
models:
  "org/model":
    context: 4096
warmup:
  - "org/model"
`
	updatedWatchYAML = `
models:
  "org/model":
    context: 8192
warmup:
  - "org/model"
`
	// Valid YAML that fails our custom validation (warmup entry has no matching pattern).
	invalidWatchYAML = `
models:
  "org/model-A":
    context: 4096
warmup:
  - "org/model-B"
`
)

func setupWatchDir(t *testing.T, content string) (dir, path string) {
	t.Helper()
	dir = t.TempDir()
	path = filepath.Join(dir, "config.yaml")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
	t.Setenv("WIRE_CONFIG", path)
	return dir, path
}

func TestWatch_SuccessfulReload(t *testing.T) {
	_, path := setupWatchDir(t, validWatchYAML)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	ch, err := Watch(ctx, slog.Default())
	if err != nil {
		t.Fatalf("Watch: %v", err)
	}

	if err := os.WriteFile(path, []byte(updatedWatchYAML), 0o600); err != nil {
		t.Fatal(err)
	}

	select {
	case cfg := <-ch:
		if cfg == nil {
			t.Fatal("received nil config")
		}
		if cfg.Models["org/model"].Context != 8192 {
			t.Errorf("context: got %d, want 8192", cfg.Models["org/model"].Context)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("timeout waiting for config reload")
	}
}

func TestWatch_InvalidConfigRejected(t *testing.T) {
	_, path := setupWatchDir(t, validWatchYAML)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	ch, err := Watch(ctx, slog.Default())
	if err != nil {
		t.Fatalf("Watch: %v", err)
	}

	if err := os.WriteFile(path, []byte(invalidWatchYAML), 0o600); err != nil {
		t.Fatal(err)
	}

	// Wait longer than the debounce; nothing should arrive.
	select {
	case cfg, ok := <-ch:
		if ok {
			t.Errorf("expected nothing on channel after invalid config, got: %+v", cfg)
		} else {
			t.Error("channel closed unexpectedly")
		}
	case <-time.After(1200 * time.Millisecond):
		// correct: invalid config was discarded
	}
}

func TestWatch_Debounce(t *testing.T) {
	_, path := setupWatchDir(t, validWatchYAML)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	ch, err := Watch(ctx, slog.Default())
	if err != nil {
		t.Fatalf("Watch: %v", err)
	}

	// Write three times in quick succession (50ms apart); total elapsed ~150ms,
	// well within the 500ms debounce window. Only the final write should produce
	// a reload.
	for i := range 3 {
		content := validWatchYAML
		if i == 2 {
			content = updatedWatchYAML
		}
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			t.Fatal(err)
		}
		time.Sleep(50 * time.Millisecond)
	}

	// Expect exactly one config after the debounce fires.
	select {
	case cfg := <-ch:
		if cfg == nil {
			t.Fatal("received nil config")
		}
		if cfg.Models["org/model"].Context != 8192 {
			t.Errorf("context: got %d, want 8192", cfg.Models["org/model"].Context)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("timeout waiting for debounced reload")
	}

	// No second reload should arrive within a short window.
	select {
	case cfg, ok := <-ch:
		if ok {
			t.Errorf("expected only one reload, got second: %+v", cfg)
		}
	case <-time.After(300 * time.Millisecond):
		// correct: only one reload emitted
	}
}

func TestWatch_ContextCancellation(t *testing.T) {
	setupWatchDir(t, validWatchYAML)

	ctx, cancel := context.WithCancel(context.Background())

	ch, err := Watch(ctx, slog.Default())
	if err != nil {
		t.Fatalf("Watch: %v", err)
	}

	cancel()

	select {
	case _, ok := <-ch:
		if ok {
			t.Error("expected channel to be closed after context cancellation")
		}
	case <-time.After(time.Second):
		t.Fatal("timeout: channel not closed after context cancellation")
	}
}

func TestWatch_WriteRenamePattern(t *testing.T) {
	// Simulate the editor write-rename pattern:
	// write new content to a temp file, then atomically rename it over the
	// config file (as vim, sed -i, etc. do). The old inode is deleted; a
	// directory-level watch must still detect the change.
	dir, path := setupWatchDir(t, validWatchYAML)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	ch, err := Watch(ctx, slog.Default())
	if err != nil {
		t.Fatalf("Watch: %v", err)
	}

	tmp := filepath.Join(dir, "config.yaml.tmp")
	if err := os.WriteFile(tmp, []byte(updatedWatchYAML), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Rename(tmp, path); err != nil {
		t.Fatal(err)
	}

	select {
	case cfg := <-ch:
		if cfg == nil {
			t.Fatal("received nil config")
		}
		if cfg.Models["org/model"].Context != 8192 {
			t.Errorf("context: got %d, want 8192", cfg.Models["org/model"].Context)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("timeout: write-rename pattern not detected")
	}
}

package cli

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"os/signal"
	"syscall"

	"github.com/nogo/wire/internal"
	"github.com/nogo/wire/internal/config"
	"github.com/nogo/wire/internal/gateway"
	"github.com/nogo/wire/internal/monitor"
	"github.com/nogo/wire/internal/process"
)

const usageText = `Usage: wire <command> [arguments]

Commands:
  up                  Start the gateway (foreground)
  version             Print version and exit

Environment:
  WIRE_CONFIG         Config file path (default: ~/.config/wire/config.yaml)
`

// Run dispatches CLI commands from the given argument slice (os.Args[1:]).
// It returns an exit code suitable for os.Exit.
func Run(args []string) int {
	if err := dispatch(args); err != nil {
		fmt.Fprintln(os.Stderr, "wire:", err)
		return 1
	}
	return 0
}

func dispatch(args []string) error {
	if len(args) == 0 {
		fmt.Print(usageText)
		return nil
	}
	switch args[0] {
	case "help", "--help", "-h":
		fmt.Print(usageText)
		return nil
	case "up":
		return runUp()
	case "version", "--version", "-v":
		fmt.Printf("wire %s (%s) built %s\n", internal.Version, internal.Commit, internal.BuildDate)
		return nil
	default:
		fmt.Print(usageText)
		return fmt.Errorf("unknown command: %q", args[0])
	}
}

func runUp() error {
	cfg, err := config.Load()
	if err != nil {
		return fmt.Errorf("loading config: %w", err)
	}

	// bgCtx drives the process manager; cancelled only after gateway drains.
	bgCtx, bgCancel := context.WithCancel(context.Background())
	defer bgCancel()

	// shutCtx is cancelled by SIGTERM/SIGINT.
	shutCtx, stop := signal.NotifyContext(bgCtx, syscall.SIGTERM, syscall.SIGINT)
	defer stop()

	mgr := process.New(cfg, slog.Default())
	if err := mgr.Start(bgCtx); err != nil {
		return fmt.Errorf("starting process manager: %w", err)
	}

	var hub *monitor.Hub
	if cfg.Monitor {
		hub = monitor.NewHub(slog.Default(), mgr.Events(), mgr.Snapshot)
		hub.Start()
		defer hub.Stop()
	}

	gw := gateway.New(cfg, mgr, hub, slog.Default())
	gwErrCh := make(chan error, 1)
	go func() { gwErrCh <- gw.ListenAndServe(shutCtx) }()

	var reloadCh <-chan *config.Config
	if ch, err := config.Watch(bgCtx, slog.Default()); err != nil {
		slog.Warn("config watcher unavailable", "err", err)
	} else {
		reloadCh = ch
	}

	slog.Info("wire ready", "listen", cfg.Listen, "version", internal.Version, "commit", internal.Commit)

	for {
		select {
		case err := <-gwErrCh:
			bgCancel()
			_ = mgr.Stop()
			if err != nil {
				return fmt.Errorf("gateway error: %w", err)
			}
			return nil

		case <-shutCtx.Done():
			if cause := context.Cause(shutCtx); cause != nil {
				slog.Info("shutting down", "cause", cause)
			}
			stop()
			if err := <-gwErrCh; err != nil {
				slog.Error("gateway shutdown error", "error", err)
			}
			bgCancel()
			return mgr.Stop()

		case newCfg, ok := <-reloadCh:
			if !ok || newCfg == nil {
				reloadCh = nil
				continue
			}
			if newCfg.Listen != cfg.Listen {
				slog.Warn("listen address change requires restart")
			}
			if newCfg.Monitor != cfg.Monitor {
				slog.Warn("monitor setting change requires restart")
			}
			slog.Info("config reloaded")
			mgr.Reload(newCfg)
			gw.UpdateConfig(newCfg)
			cfg = newCfg
		}
	}
}

package monitor

import (
	"bytes"
	"log/slog"
	"regexp"
	"strconv"
	"time"
)

// Compiled regexes for llama-server stderr patterns.
// Initialised once at package init — never per-line.
var (
	rePromptEval = regexp.MustCompile(
		`prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens\s*\([^,]+,\s*([\d.]+)\s*tokens(?:/s| per second)\)`)
	// reGenEval matches "eval time" lines; checked after rePromptEval so
	// "prompt eval time" lines are never reached here.
	reGenEval = regexp.MustCompile(
		`\beval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens\s*\([^,]+,\s*([\d.]+)\s*tokens(?:/s| per second)\)`)
	reSlotProc  = regexp.MustCompile(`slot\s+(?:(\d+)\s+is\s+processing|launch_slot_:\s+id\s+(\d+)\s+\|.*\|\s+processing task)`)
	reSlotRel   = regexp.MustCompile(`slot\s+(?:(\d+)\s+released|release:\s+id\s+(\d+)\s+\|.*\|\s+stop processing)`)
	reModelLoad = regexp.MustCompile(`load_tensors:\s+offloading\s+(\d+)\s+(?:repeating\s+)?layers\s+to\s+GPU`)
	reVRAMAlloc = regexp.MustCompile(`load_tensors:\s+\S+\s+(?:model\s+)?buffer\s+size\s*=\s*([\d.]+)\s*MiB`)
	reListen    = regexp.MustCompile(`server is listening on http://[\d.]+:(\d+)`)
)

// EventParser implements io.Writer. It buffers bytes, splits on newlines,
// writes each complete line to slog.Debug (preserving existing behaviour), and
// sends a structured ServerEvent to ch. Sends are non-blocking; if ch is full
// the event is dropped and Dropped is incremented.
type EventParser struct {
	log     *slog.Logger
	name    string
	ch      chan<- ServerEvent
	buf     bytes.Buffer
	Dropped uint64

	// PortCh receives the listening port parsed from llama-server stdout.
	// Sent at most once; buffered so the parser never blocks.
	PortCh chan int
}

// NewEventParser returns an EventParser for the named backend.
func NewEventParser(log *slog.Logger, name string, ch chan<- ServerEvent) *EventParser {
	return &EventParser{log: log, name: name, ch: ch, PortCh: make(chan int, 1)}
}

func (p *EventParser) Write(data []byte) (int, error) {
	p.buf.Write(data)
	for {
		b := p.buf.Bytes()
		idx := bytes.IndexByte(b, '\n')
		if idx < 0 {
			break
		}
		line := string(b[:idx])
		p.buf.Next(idx + 1)
		if len(line) == 0 {
			continue
		}
		p.log.Debug(line, "backend", p.name)
		ev := p.parse(line)
		select {
		case p.ch <- ev:
		default:
			p.Dropped++
		}
	}
	return len(data), nil
}

func (p *EventParser) parse(line string) ServerEvent {
	ev := ServerEvent{
		Time:    time.Now(),
		Backend: p.name,
		Slot:    -1,
	}

	if m := rePromptEval.FindStringSubmatch(line); m != nil {
		ev.Kind = EventPromptEval
		ev.DurationMs, _ = strconv.ParseFloat(m[1], 64)
		ev.Tokens, _ = strconv.Atoi(m[2])
		ev.TokPerSec, _ = strconv.ParseFloat(m[3], 64)
		return ev
	}

	if m := reGenEval.FindStringSubmatch(line); m != nil {
		ev.Kind = EventGenEval
		ev.DurationMs, _ = strconv.ParseFloat(m[1], 64)
		ev.Tokens, _ = strconv.Atoi(m[2])
		ev.TokPerSec, _ = strconv.ParseFloat(m[3], 64)
		return ev
	}

	if m := reSlotProc.FindStringSubmatch(line); m != nil {
		ev.Kind = EventSlotAssign
		ev.Slot, _ = strconv.Atoi(firstNonEmpty(m[1], m[2]))
		return ev
	}

	if m := reSlotRel.FindStringSubmatch(line); m != nil {
		ev.Kind = EventSlotRelease
		ev.Slot, _ = strconv.Atoi(firstNonEmpty(m[1], m[2]))
		return ev
	}

	if reModelLoad.MatchString(line) {
		ev.Kind = EventModelLoad
		ev.Message = line
		return ev
	}

	if reVRAMAlloc.MatchString(line) {
		ev.Kind = EventVRAMAlloc
		ev.Message = line
		return ev
	}

	if m := reListen.FindStringSubmatch(line); m != nil {
		if port, err := strconv.Atoi(m[1]); err == nil {
			select {
			case p.PortCh <- port:
			default:
			}
		}
		ev.Kind = EventRaw
		ev.Message = line
		return ev
	}

	ev.Kind = EventRaw
	ev.Message = line
	return ev
}

// firstNonEmpty returns the first non-empty string from its arguments.
func firstNonEmpty(ss ...string) string {
	for _, s := range ss {
		if s != "" {
			return s
		}
	}
	return ""
}

